from typing import Dict, Set, Tuple
import numpy as np

from config import MVPConfig, MVP_CONFIG


def config_bag(edge_scores: Dict[str, float], B: int = 10) -> Dict[str, float]:
    """2D anti-chain config bagging.

    Uses (node_threshold, edge_threshold) pairs along an anti-diagonal
    to produce pairwise-incomparable circuits (no nesting).
    """
    if not edge_scores:
        return {}

    edges = list(edge_scores.keys())
    scores = np.array([edge_scores[e] for e in edges])
    abs_scores = np.abs(scores)

    node_max: Dict[str, float] = {}
    for e, s in edge_scores.items():
        src = e.split("->")[0]
        node_max[src] = max(node_max.get(src, -np.inf), abs(s))

    node_scores = np.array([node_max[e.split("->")[0]] for e in edges])

    t = np.linspace(0, 1, B)
    node_pcts = 10 + 80 * t
    edge_pcts = 10 + 80 * (1 - t)

    node_threshs = np.percentile(node_scores, node_pcts)
    edge_threshs = np.percentile(abs_scores, edge_pcts)

    stability = np.zeros(len(edges))
    for nt, et in zip(node_threshs, edge_threshs):
        included = (node_scores >= nt) & (abs_scores >= et)
        stability += included.astype(float)
    stability /= B

    return {edge: float(stab) for edge, stab in zip(edges, stability)}


def get_circus_tiers(stability_scores: Dict[str, float], core_threshold: float = 1.0, contingent_threshold: float = 0.5) -> Dict[str, str]:
    tiers = {}
    for edge, score in stability_scores.items():
        if score >= core_threshold:
            tiers[edge] = "core"
        elif score >= contingent_threshold:
            tiers[edge] = "contingent"
        else:
            tiers[edge] = "noise"
    return tiers


def get_tier_sets(tiers: Dict[str, str]) -> Dict[str, Set[str]]:
    result: Dict[str, Set[str]] = {"core": set(), "contingent": set(), "noise": set()}
    for edge, tier in tiers.items():
        result[tier].add(edge)
    return result


def run_circus(edge_scores: Dict[str, float], config: MVPConfig = MVP_CONFIG) -> Tuple[Dict[str, float], Dict[str, str]]:
    stability = config_bag(edge_scores, B=config.circus_B)
    tiers = get_circus_tiers(stability, core_threshold=config.circus_core_threshold, contingent_threshold=config.circus_contingent_threshold)

    tier_counts = {}
    for t in ["core", "contingent", "noise"]:
        tier_counts[t] = sum(1 for v in tiers.values() if v == t)
    print(f"CIRCUS tiers: {tier_counts}")

    return stability, tiers
